function plannedKm(tid,seconds){const timetable=geo.timetable.filter(s=>s.train_id===tid),points=[];for(const stop of timetable)for(const key of ['scheduled_arrival','scheduled_departure'])if(stop[key])points.push([Date.parse(stop[key]),geo.stations.find(s=>s.id===stop.station_id).km]);points.sort((a,b)=>a[0]-b[0]);const ms=Date.parse(snap.ts)+seconds*1000;if(ms<=points[0][0])return points[0][1];for(let i=1;i<points.length;i++)if(ms<=points[i][0]){const [a,x]=points[i-1],[b,y]=points[i];return x+(y-x)*(ms-a)/(b-a||1);}return points.at(-1)[1];}
function diagramScale(){const step=Number($('horizon').value),window=zoomWindow||[-step,step*2],x=m=>185+(m-window[0])/(window[1]-window[0])*670;const y=km=>{if($('axis').value==='km')return 18+km/geo.length_km*210;let i=geo.stations.findIndex((s,j)=>j<8&&km>=s.km&&km<=geo.stations[j+1].km);if(i<0)i=7;return 18+(i+(km-geo.stations[i].km)/(geo.stations[i+1].km-geo.stations[i].km))*26.25;};return {window,x,y,step};}
function renderDiagram(){if(!snap)return;const {window:[lo,hi],x,y,step}=diagramScale();let svg='<defs><pattern id="closure-hatch" width="8" height="8" patternUnits="userSpaceOnUse"><path d="M0 8 8 0" stroke="'+colors.red+'" opacity=".35"/></pattern><clipPath id="plot"><rect x="185" y="10" width="670" height="222"/></clipPath></defs>';let lastLabel=-50;for(const s of geo.stations){const py=y(s.km),labelY=Math.max(py,lastLabel+18);lastLabel=labelY;svg+=`<line x1="185" x2="855" y1="${py}" y2="${py}" stroke="${colors.line}"/><path d="M165 ${labelY} 180 ${py}" stroke="${colors.line}" fill="none"/><text x="160" y="${labelY+4}" text-anchor="end">${esc(s.name)}</text>`;}
 const ticks=[];for(let m=Math.ceil(lo/step)*step;m<=hi;m+=step)ticks.push(m);if(!ticks.includes(0)&&lo<=0&&hi>=0)ticks.push(0);for(const m of ticks){const label=new Date(Date.parse(snap.ts)+m*60000).toLocaleTimeString(lang==='kk'?'kk-KZ':'ru-RU',{timeZone:'Asia/Almaty',hour:'2-digit',minute:'2-digit',hour12:false});svg+=`<line x1="${x(m)}" x2="${x(m)}" y1="10" y2="235" stroke="${m===0?colors.ink:colors.line}"/><text x="${x(m)}" y="260" text-anchor="middle">${m===0?T('now'):label}</text>`;}
 svg+='<g clip-path="url(#plot)">';if(snap.incident_active&&['closure','chaos'].includes(incident))svg+=`<rect x="${x(Math.max(lo,0))}" y="${y(65)}" width="${Math.max(0,x(Math.min(hi,(snap.incident_end_s-elapsed)/60))-x(Math.max(lo,0)))}" height="${y(174)-y(65)}" fill="url(#closure-hatch)"/>`;
 for(const d of snap.display){const t=snap.state.trains.find(t=>t.train_id===d.train_id),chosen=d.train_id===selected,col=typeColor(t),past=history.filter(s=>s.elapsed_s<=elapsed&&s.elapsed_s>=elapsed+lo*60).map(s=>({m:(s.elapsed_s-elapsed)/60,d:s.display.find(v=>v.train_id===d.train_id)})).filter(v=>v.d);const plan=Array.from({length:50},(_,i)=>{const m=lo+(hi-lo)*i/49;return `${x(m)},${y(plannedKm(d.train_id,m*60))}`;}).join(' ');const routeEnds=[d.origin,d.destination].map(id=>geo.stations.find(s=>s.id===id).km),end=clamp(d.corridor_km+d.direction*t.speed*hi/60,Math.min(...routeEnds),Math.max(...routeEnds));svg+=`<g data-train="${d.train_id}" role="button" tabindex="0" opacity="${chosen?1:.3}"><polyline points="${plan}" stroke="${col}" fill="none" stroke-width="1"/><polyline points="${past.map(p=>`${x(p.m)},${y(p.d.corridor_km)}`).join(' ')}" stroke="${col}" fill="none" stroke-width="${chosen?3:2}"/><line x1="${x(0)}" y1="${y(d.corridor_km)}" x2="${x(hi)}" y2="${y(end)}" stroke="${col}" stroke-width="${chosen?3:1.5}" stroke-dasharray="6 4"/><line x1="${x(0)}" y1="${y(d.corridor_km)}" x2="${x(hi)}" y2="${y(end)}" stroke="transparent" stroke-width="12"/><circle cx="${x(0)}" cy="${y(d.corridor_km)}" r="${chosen?5:2}" fill="${col}"/><title>${shortId(d.train_id)} · ${T(kind(t))}</title></g>`;}
 svg+='</g>';const focused=document.activeElement?.closest('#diagram [data-train]')?.dataset.train;$('diagram').innerHTML=svg;if(focused)$('diagram').querySelector(`[data-train="${CSS.escape(focused)}"]`)?.focus({preventScroll:true});}
function renderStation(){if(!snap)return;const s=geo.stations.find(s=>s.id===stationId),v=snap.stations.find(v=>v.id===stationId);let svg='';for(let i=0;i<s.tracks;i++){const yy=35+i*38;svg+=`<path d="M15 100 65 ${yy}H335L385 100" fill="none" stroke="${colors.line}" stroke-width="2"/><text x="70" y="${yy-10}">${T('track',{n:i+1})}</text>`;if(v.trains[i])svg+=`<g data-train="${v.trains[i]}" role="button" tabindex="0"><rect x="120" y="${yy-6}" width="150" height="12" rx="3" fill="${colors.green}"/><text x="280" y="${yy+5}">${shortId(v.trains[i])}</text></g>`;}svg+=`<text x="16" y="200">${T('freeTracks',{n:v.capacity-v.occupied,m:v.capacity})}</text>`;const focused=document.activeElement?.closest('#station [data-train]')?.dataset.train;$('station').innerHTML=svg;if(focused)$('station').querySelector(`[data-train="${CSS.escape(focused)}"]`)?.focus({preventScroll:true});const arrivals=geo.timetable.filter(a=>a.station_id===stationId&&a.scheduled_arrival&&Date.parse(a.scheduled_arrival)>=Date.parse(snap.ts)&&Date.parse(a.scheduled_arrival)<=Date.parse(snap.ts)+3600000);$('station-facts').innerHTML=Array.from({length:s.tracks},(_,i)=>`<div>${T('track',{n:i+1})}: ${v.trains[i]?T('occupied')+' · '+shortId(v.trains[i]):T('free')}</div>`).join('')+`<p>${T('stationNote')}</p><p>${T('futureOccupancy')}</p><h3>${T('arrivals')}</h3>`+arrivals.map(a=>`<div>${shortId(a.train_id)} · ${clock(a.scheduled_arrival)}</div>`).join('');}
function frame(now){requestAnimationFrame(frame);if(document.hidden||now-lastFrame<(!playing||reduced?250:tempo===10?32:16))return;const start=performance.now();renderMap(now);frameDurations.push(performance.now()-start);frameDurations=frameDurations.slice(-240);lastFrame=now;}
function buildDecision(){const seed=Number($('seed').value)||42;const pool=snap.display.filter(d=>d.origin==='KOK'||d.destination==='KOK');const pair=[pool.find(d=>d.direction===1),pool.find(d=>d.direction===-1)].filter(Boolean);if(pair.length<2)return;const start=performance.now(),jobs=pair.map((d,i)=>({id:d.train_id,release:Math.round((seed*(i+3)%13)+snap.state.trains.find(t=>t.train_id===d.train_id).delay_s/60),duration:8+(seed+i*7)%9}));const opening=Math.max(0,(snap.incident_end_s-elapsed)/60);function run(order,hold=false){let time=opening+(hold?5:0);let total=0,energy=0;const slots=[];for(const index of order){const j=jobs[index],begin=Math.max(time,j.release),duration=j.duration*(hold?2:1);total+=begin-j.release;energy+=duration*(hold?.5:1)**2;slots.push({id:j.id,start:begin,end:begin+duration});time=begin+duration+2;}return {delay:total,conflicts:0,energy,slots,score:Math.max(0,100-total/2),ms:0};}const alternatives={A:run([0,1]),B:run([1,0]),C:run([0,1],true)};const fifo=run(jobs[0].release<=jobs[1].release?[0,1]:[1,0]);const ms=performance.now()-start;Object.values(alternatives).forEach(a=>a.ms=ms);fifo.ms=ms;previewChoice=null;decision={seed,ts:snap.ts,elapsed:snap.elapsed_s,incident:snap.incident,incidentAt,jobs,alternatives,fifo,selected:null};renderDecisionText();$('human').hidden=false;document.body.dataset.focus='true';decisionStart=performance.now();clearInterval(decisionTimer);decisionTimer=setInterval(()=>{const left=Math.max(0,20-Math.floor((performance.now()-decisionStart)/1000));$('decision-time').textContent=left;if(!left)choose('C',true);},200);renderComparison();}
function renderDecisionText(){
  if(!decision)return;
  const focused=document.activeElement?.closest('[data-choice]')?.dataset.choice;
  $('choices').innerHTML=Object.entries(decision.alternatives).map(([key,a],i)=>`<button data-choice="${key}">${T(key==='A'?'firstTrain':key==='B'?'secondTrain':'holdBoth',{id:shortId(decision.jobs[i===1?1:0].id)})}<small>${key==='C'?T('holdNote'):T('choiceResult',{delay:fmt(a.delay,1),conflicts:a.conflicts,delta:fmt(a.score-decision.fifo.score,1)})}</small></button>`).join('');
  if(focused)$('choices').querySelector(`[data-choice="${focused}"]`)?.focus({preventScroll:true});
  if(previewChoice){const a=decision.alternatives[previewChoice];$('choice-preview').textContent=T('choiceResult',{delay:fmt(a.delay,1),conflicts:a.conflicts,delta:fmt(a.score-decision.fifo.score,1)});}else $('choice-preview').textContent='';
  $('decision-log').textContent=decision.selected?T(decision.timed?'timeoutChoice':'selectedChoice',{choice:decision.selected})+' · '+clock(decision.chosenAt)+' · '+decisionCheckText():'';
}
function decisionCheckText(){if(!decision?.selected)return '';if(decision.validation==='pending')return T('decisionChecking');if(decision.validation==='error')return T('decisionCheckError');if(!decision.validation)return '';const result=decision.validation;if(result.accepted)return T('decisionAccepted');const codes=[...new Set(result.actions.flatMap(a=>a.issue_codes))];return T('decisionRejected')+(codes.length?' · '+codes.map(code=>T('issue_'+code)).join(', '):'');}
async function choose(key,timed=false){if(!decision||decision.selected)return;const game=decision;game.selected=key;game.timed=timed;game.chosenAt=snap.ts;game.validation='pending';clearInterval(decisionTimer);$('human').hidden=true;document.body.dataset.focus='false';renderDecisionText();renderComparison();navigate('comparison');try{const result=await api('/dispatch/decision',{elapsed_s:game.elapsed,incident:game.incident,incident_at_s:game.incidentAt,seed:game.seed,choice:key});if(result.snapshot_time!==game.ts||result.choice!==key)throw Error('snapshot mismatch');if(decision===game)game.validation=result;}catch{if(decision===game)game.validation='error';}if(decision===game)renderDecisionText();}
function renderComparison(){const body=$('comparison-body');const rows=[['humanStrategy',decision?.selected?decision.alternatives[decision.selected]:null],['FIFO',decision?.fifo],['CP-SAT',null],['CP-SAT + ML',null]];body.innerHTML=rows.map(([name,r])=>`<tr><td>${['humanStrategy'].includes(name)?T(name):name}</td>${r?`<td>${fmt(r.delay,1)}</td><td>${r.conflicts}</td><td>${fmt(r.ms,2)}</td><td>${fmt(r.energy,1)}</td>`:Array.from({length:4},()=>`<td>${T(name.startsWith('CP')?'notConnected':'noDecision')}</td>`).join('')}</tr>`).join('');}
async function loadEvidence(){evidenceLoaded=true;const e=$('evidence');try{const data=await api('/evidence.json');const table=(heads,rows)=>`<table><thead><tr>${heads.map(k=>`<th>${T(k)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(v=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table>`;
 const cal=data.growth_metrics.calibration;const calChart=`<svg viewBox="0 0 420 280"><path d="M45 20V235H395M45 235 395 20" fill="none" stroke="${colors.line}"/><polyline points="${cal.map(p=>`${45+p.predicted*350},${235-p.observed*215}`).join(' ')}" fill="none" stroke="${colors.green}" stroke-width="3"/>${[0,.25,.5,.75,1].map(n=>`<text x="${45+n*350}" y="260" text-anchor="middle">${n}</text><text x="30" y="${235-n*215}" text-anchor="end">${n}</text>`).join('')}</svg>`;
 const points=data.replay.points,range=Math.max(3,...points.map(p=>Math.abs(p.actual)),...points.map(p=>Math.abs(p.predicted))),line=key=>points.map((p,i)=>`${45+i/Math.max(1,points.length-1)*350},${135-p[key]/range*100}`).join(' ');const replay=`<svg viewBox="0 0 420 280"><path d="M45 20V235H395M45 135H395" fill="none" stroke="${colors.line}"/><polyline points="${line('actual')}" fill="none" stroke="${css('--freight')}" stroke-width="2"/><polyline points="${line('predicted')}" fill="none" stroke="${colors.green}" stroke-width="2"/>${[0,Math.floor(points.length/2),points.length-1].map(i=>`<text x="${45+i/Math.max(1,points.length-1)*350}" y="260" text-anchor="middle">${points[i].stop}</text>`).join('')}<text x="12" y="38">${fmt(range,0)}</text><text x="12" y="139">0</text><text x="8" y="238">−${fmt(range,0)}</text></svg>`;
 const shap=Object.entries(data.shap).sort((a,b)=>b[1]-a[1]).slice(0,8);let labels={};try{labels=await api('/locales/features-'+lang+'.json');}catch{}e.innerHTML=`<section class="full"><h3>${T('modelCard')}</h3><p>${T('modelCardText')}</p><span class="badge">${data.model_info.model_version}</span> <span class="badge">${data.model_info.rows.test.toLocaleString()} ${T('testRows')}</span><p>MAE ${fmt(data.model_info.regression.mae,3)} ${T('min')} · Brier ${fmt(data.growth_metrics.brier,4)} · ECE ${fmt(data.growth_metrics.ece,4)}</p></section><section class="full"><h3>${T('baselines')}</h3>${table(['bucket','model','zero','edgeMedian'],data.buckets.map(b=>[b.bucket==='all'?T('all'):b.bucket,...['model','zero','p50'].map(k=>fmt(b[k],3))]))}</section><section><h3>${T('calibration')}</h3><p>${T('calibrationNote')}</p>${calChart}</section><section><h3>${T('shap')}</h3><p>${T('shapNote')}</p>${shap.map(([key,n])=>`<div class="factor"><span>${esc(labels[key]||key)}</span><span>${fmt(n,3)}</span><div class="factor-track"><div class="factor-bar" style="transform:scaleX(${n/shap[0][1]})"></div></div></div>`).join('')}</section><section><h3>${T('replayPkp')} · ${data.replay.run_id}</h3><p>${T('replayNote')}</p>${replay}</section><section><h3>${T('whyNot')}</h3><p>${T('memorization')}</p><p>${T('formula')}</p><h3>${T('residualValidation')}</h3>${table(['bucket','formulaMaе','residualMae'],data.kz_group_folds.map(f=>[f.held_segments.join(' / '),fmt(f.formula_mae,2),fmt(f.residual_mae,2)]))}</section>`;}catch{e.textContent=T('requestError');}}
async function ask(question){if(chatBusy||!snap)return;chatBusy=true;$('send').disabled=true;const snapshot=currentState(),chosen=selected;const add=(text,cls='')=>{const p=document.createElement('p');p.className='message '+cls;p.textContent=text;$('messages').append(p);return p;};add(question,'user');const reply=add(T('checking'));$('chat-context').textContent=clock(snap.ts)+' · '+shortId(chosen)+' · '+T('chatBoundary');const a=advisories.find(a=>a.train_id===chosen);if(lang==='kk'){reply.textContent=T('chatLocalKk',{id:shortId(chosen),delay:fmt(train().delay_s/60,0),wait:fmt(a?.known_wait_min||0,0)});chatBusy=false;$('send').disabled=false;return;}
 const abort=new AbortController(),timeout=setTimeout(()=>abort.abort(),90000);try{const r=await fetch('/chat',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({messages:[...chatHistory.slice(-8),{role:'user',content:question+'\nВыбран '+chosen+'. KZ перенос не проверен. Не выдавай PKP число за надёжный прогноз. Известное ожидание: '+(a?.known_wait_min??'неизвестно')+' мин.'}],state:snapshot,session_id:'turkisib-redesign'}),signal:abort.signal});if(!r.ok)throw Error();const reader=r.body.getReader(),decoder=new TextDecoder();let buffer='',answer='',done=false;while(true){const chunk=await reader.read();buffer+=decoder.decode(chunk.value||new Uint8Array(),{stream:!chunk.done});let idx;while((idx=buffer.indexOf('\n\n'))>=0){const raw=buffer.slice(0,idx);buffer=buffer.slice(idx+2);const event=raw.split('\n').find(l=>l.startsWith('event:'))?.slice(6).trim(),line=raw.split('\n').find(l=>l.startsWith('data:'));if(!line)continue;const data=JSON.parse(line.slice(5));if(event==='token'){answer+=data.text;reply.textContent=answer;}if(event==='done')done=true;}if(chunk.done)break;}$('messages').scrollTop=$('messages').scrollHeight;if(!done||!answer)throw Error();if(a&&!a.reliable)reply.textContent=T('unreliable')+'. '+T('pkpTransfer')+'. '+T('knownWait')+': '+minute(a.known_wait_min||0)+'.\n'+answer;chatHistory.push({role:'user',content:question},{role:'assistant',content:reply.textContent});}catch{reply.textContent=T('chatError');}finally{clearTimeout(timeout);chatBusy=false;$('send').disabled=false;}}
function showTour(){const steps=[['tourMap','tourMapText','overview'],['tourIncident','tourIncidentText','scenarios'],['tourModel','tourModelText','lab'],['tourCompare','tourCompareText','comparison']];const [title,text,dest]=steps[tourStep%steps.length];$('tour').hidden=false;$('tour-title').textContent=T(title);$('tour-text').textContent=T(text);navigate(dest);}
async function changeIncident(value){incident=value;incidentAt=elapsed;ack=false;document.body.dataset.ack='false';$('incident').value=value;pause();experiment=null;try{applySnapshot(await api('/demo/snapshot?'+new URLSearchParams({elapsed,incident,incident_at:incidentAt})));calculate();resume();if(value!=='none'){buildDecision();$('focus-incident').click();$('choices').querySelector('button')?.focus({preventScroll:true});}else{clearInterval(decisionTimer);$('human').hidden=true;document.body.dataset.focus='false';}}catch(e){error(e.message);}}
