['delay','reserve'].forEach(id=>$(id).oninput=()=>{pause();experiment={id:selected,delay:Number($('delay').value),reserve:Number($('reserve').value)};renderInspector();calculate();});$('clear-experiment').onclick=()=>{experiment=null;renderInspector();calculate();};$('replay').oninput=()=>{pause();replaying=true;experiment=null;applySnapshot(history[Number($('replay').value)],false);$('replay-label').textContent=clock(snap.ts);calculate();};$('live').onclick=()=>{if(history.length)applySnapshot(history.at(-1),false);resume();};$('csv').onclick=()=>{const rows=['timestamp,train_id,block_id,km,speed_kmh,delay_s'];for(const s of history)for(const t of s.state.trains)rows.push([s.ts,t.train_id,t.position.block_id,t.position.km,t.speed,t.delay_s].join(','));const url=URL.createObjectURL(new Blob(['\ufeff'+rows.join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='turkisib-kz-demo.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
