$('axis').onchange=renderDiagram;$('horizon').onchange=()=>{zoomWindow=null;renderDiagram();};$('zoom-reset').onclick=()=>{zoomWindow=null;renderDiagram();};$('diagram').onpointerdown=e=>{if(e.target.closest('[data-train]'))return;dragStart=e.clientX;};$('diagram').onpointerup=e=>{if(dragStart===null)return;const rect=$('diagram').getBoundingClientRect(),{window:[lo,hi]}=diagramScale(),toTime=x=>lo+clamp(((x-rect.left)/rect.width*880-185)/670,0,1)*(hi-lo);if(Math.abs(e.clientX-dragStart)>20){zoomWindow=[toTime(Math.min(dragStart,e.clientX)),toTime(Math.max(dragStart,e.clientX))];renderDiagram();}dragStart=null;};$('diagram').onpointermove=e=>{const rect=$('diagram').getBoundingClientRect(),{window:[lo,hi]}=diagramScale(),m=lo+clamp(((e.clientX-rect.left)/rect.width*880-185)/670,0,1)*(hi-lo);$('crosshair').textContent=new Date(Date.parse(snap.ts)+m*60000).toLocaleTimeString(lang==='kk'?'kk-KZ':'ru-RU',{timeZone:'Asia/Almaty',hour12:false})+' · '+T('dragZoom');};
