async function start(){try{const [ru,kk]=await Promise.all([fetch('/locales/ru.json').then(r=>r.json()),fetch('/locales/kk.json').then(r=>r.json())]);await i18next.init({lng:lang,fallbackLng:'ru',resources:{ru:{translation:ru},kk:{translation:kk}},interpolation:{escapeValue:false}});setTheme(localStorage.getItem('turkisib-theme')||'light');localize();const [g,c,s,h]=await Promise.all([api('/infra/geometry'),api('/kazakhstan.geojson'),api('/demo/snapshot'),api('/health')]);geo=g;country=c;selected=s.state.trains[0].train_id;$('train-picker').innerHTML=s.state.trains.map(t=>`<option value="${t.train_id}">${shortId(t.train_id)} · ${T(kind(t))} · ${s.display.find(d=>d.train_id===t.train_id).origin}</option>`).join('');$('station-picker').innerHTML=geo.stations.map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('');$('station-picker').value=stationId;$('chat-provider').textContent=T(h.llm_configured?'llmReady':'llmFallback');applySnapshot(s);calculate();initializeMap();$('play').disabled=false;connect();requestAnimationFrame(frame);renderComparison();if(location.hash==='#lab')navigate('lab');}catch(e){error(e.message||'Service unavailable');}}
let analysisResult=null,analysisBusy=false,analysisInitialized=false;
function planStatus(status){const key={OPTIMAL:'planOptimal',FEASIBLE:'planFeasible',INFEASIBLE:'planInfeasible',TIMEOUT:'planTimeout',NOT_REQUESTED:'planNotRequested',UNAVAILABLE:'analysisUnavailable',UNSUPPORTED_SCENARIO:'analysisUnsupported'}[status];return key?T(key):status||'—';}
function renderAnalysis(){
  if(!analysisResult)return;
  const r=analysisResult,c=r.cp_sat;
  $('platform-results').hidden=false;
  $('analysis-snapshot').textContent=clock(r.snapshot_time)+' · '+r.snapshot_id;
  $('analysis-fifo').textContent=T('analysisCount',{count:r.fifo.ordered_train_ids.length});
  $('analysis-cpsat').textContent=planStatus(c.status)+(c.reservation_count?' · '+T('reservationCount',{count:c.reservation_count}):'');
  $('analysis-validator').textContent=c.valid===true?T('analysisValid'):c.valid===false?T('analysisInvalid'):T('analysisNotChecked');
  $('analysis-order').textContent=r.fifo.ordered_train_ids.join(' → ');
  const rows=(c.reservations||[]).filter(v=>v.train_id===selected&&v.resource_type==='block').slice(0,12);
  $('analysis-reservations').innerHTML=rows.length?rows.map(v=>`<div class="reservation-row"><span>${esc(v.resource_id)}</span><span class="mono">${clock(v.start)}–${clock(v.end)}</span></div>`).join(''):T('noReservations');
  $('analysis-scope').textContent=T('pairLabel')+': '+r.pair_train_ids.join(' / ')+' · '+T('reservationCount',{count:c.reservation_count||0})+' · '+T('plannerSeed')+': '+r.seed+' · '+T('fullCpSatLabel')+': '+planStatus(r.full_cp_sat?.status);
  $('analysis-limitations').textContent=(r.snapshot_overlaps?.length?T('snapshotOverlap',{count:r.snapshot_overlaps.length})+' ':'')+T('analysisLimitations');
  $('platform-status').textContent=Math.abs((snap?.elapsed_s??r.elapsed_s)-r.elapsed_s)>1||incident!==r.incident||incidentAt!==r.incident_at_s?T('analysisStale'):T('analysisReady');
}
async function runAnalysis(){
  if(!snap||analysisBusy)return;
  const captured={elapsed_s:snap.elapsed_s,incident:snap.incident,incident_at_s:incidentAt,seed:Number($('seed').value)||42};
  const restoreFocus=document.activeElement===$('run-analysis');
  analysisBusy=true;$('run-analysis').disabled=true;$('platform-status').textContent=T('analysisLoading');
  try{analysisResult=await api('/dispatch/analysis',captured);renderAnalysis();}
  catch{analysisResult=null;$('platform-results').hidden=true;$('platform-status').textContent=T('analysisError');}
  finally{analysisBusy=false;$('run-analysis').disabled=false;if(restoreFocus)$('run-analysis').focus({preventScroll:true});}
}
$('run-analysis').onclick=runAnalysis;
i18next.on('languageChanged',()=>{if(analysisResult)renderAnalysis();});
start();
